def calc(expr,value):return eq(expr.replace('*',chr(92)+'times').replace('/',chr(92)+'div'),value)
def C(prompt,method,expr,value,unit):return q(prompt,method,calc(expr,value),f'{value} {unit}.')
def E(title,intro,qs,params=None,figures=None):
 item=ex(title,intro,qs,figures=figures);item['parametres']=params or {};return item
